// --- Yönetici: kullanıcı aboneliklerini elle onaylama/uzatma ---
import React, { useEffect, useMemo, useState } from 'react';
import { CheckCircle, PauseCircle, RotateCcw, Save, Trash2, Mail } from 'lucide-react';
import {
  subscribeAllSubscriptions, updateSubscription, Timestamp,
  subscribeAllPaymentRequests, updatePaymentRequest, subscribePaymentInfo, setPaymentInfo,
  subscribePricingPlans, setPricingPlans, purgeExpiredUser,
} from '../firebase';
import { formatDateShort, toDate } from '../utils';
import { PLAN_OPTIONS } from '../constants';
import {
  PageHeader, Card, Table, Td, Badge, EmptyState, FormModal, Field, Input, Select, Button,
} from '../components/ui';

const planLabel = (key) => PLAN_OPTIONS.find((p) => p.key === key)?.label || '-';
const PLAN_DAYS = { '1m': 30, '3m': 90, '6m': 180, '12m': 365 };
const GRACE_MS = 90 * 24 * 60 * 60 * 1000; // aboneliği yenilenmeyen hesaplar için 3 aylık saklama süresi

// Süresi dolmuş (ve henüz yenilenmemiş) bir aboneliğin ne zaman doldu ve
// 3 aylık saklama süresinin dolup dolmadığını hesaplar. Halen aktif/deneme
// süresi devam eden veya askıya alınmış/silinmiş hesaplar için null döner.
function expiryInfo(sub) {
  if (!sub || sub.status === 'deleted' || sub.status === 'suspended') return null;
  const raw = sub.status === 'active' ? sub.expiresAt : sub.status === 'trial' ? sub.trialEndsAt : null;
  if (!raw) return null;
  const expiredAt = toDate(raw).getTime();
  if (expiredAt >= Date.now()) return null;
  const deadline = expiredAt + GRACE_MS;
  return { expiredAt, deadline, overdue: Date.now() > deadline };
}

function PaymentInfoCard() {
  const [form, setForm] = useState({ bankName: '', accountHolder: '', iban: '', note: '' });
  const [saved, setSaved] = useState(false);

  useEffect(() => subscribePaymentInfo((d) => {
    if (d) setForm({ bankName: d.bankName || '', accountHolder: d.accountHolder || '', iban: d.iban || '', note: d.note || '' });
  }), []);

  const save = async (e) => {
    e.preventDefault();
    await setPaymentInfo(form);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  return (
    <Card title="Ödeme Alınacak Hesap Bilgileri" className="mb-6">
      <form onSubmit={save} className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <Field label="Banka Adı"><Input value={form.bankName} onChange={(e) => setForm({ ...form, bankName: e.target.value })} /></Field>
        <Field label="Hesap Sahibi"><Input value={form.accountHolder} onChange={(e) => setForm({ ...form, accountHolder: e.target.value })} /></Field>
        <Field label="IBAN" className="md:col-span-2"><Input value={form.iban} onChange={(e) => setForm({ ...form, iban: e.target.value })} /></Field>
        <Field label="Not (opsiyonel)" className="md:col-span-2"><Input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} placeholder="örn. Açıklama kısmına e-posta adresinizi yazınız" /></Field>
        <div className="md:col-span-2 flex items-center gap-3">
          <Button type="submit" icon={Save}>Kaydet</Button>
          {saved && <span className="text-sm text-green-600">Kaydedildi ✓</span>}
        </div>
      </form>
    </Card>
  );
}

function PricingPlansCard() {
  const [form, setForm] = useState({ '1m': '', '3m': '', '6m': '', '12m': '' });
  const [saved, setSaved] = useState(false);

  useEffect(() => subscribePricingPlans((d) => {
    if (d) setForm({ '1m': d['1m'] || '', '3m': d['3m'] || '', '6m': d['6m'] || '', '12m': d['12m'] || '' });
  }), []);

  const save = async (e) => {
    e.preventDefault();
    await setPricingPlans({
      '1m': Number(form['1m']) || 0,
      '3m': Number(form['3m']) || 0,
      '6m': Number(form['6m']) || 0,
      '12m': Number(form['12m']) || 0,
    });
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  return (
    <Card title="Abonelik Paketi Fiyatları" className="mb-6">
      <form onSubmit={save} className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        {PLAN_OPTIONS.map((p) => (
          <Field key={p.key} label={`${p.label} (₺)`}>
            <Input type="number" step="0.01" value={form[p.key]} onChange={(e) => setForm({ ...form, [p.key]: e.target.value })} />
          </Field>
        ))}
        <div className="md:col-span-2 flex items-center gap-3">
          <Button type="submit" icon={Save}>Kaydet</Button>
          {saved && <span className="text-sm text-green-600">Kaydedildi ✓</span>}
        </div>
      </form>
    </Card>
  );
}

const STATUS_META = {
  trial: { label: 'Deneme', color: 'blue' },
  active: { label: 'Aktif', color: 'green' },
  expired: { label: 'Süresi Doldu', color: 'red' },
  suspended: { label: 'Askıda', color: 'yellow' },
  deleted: { label: 'Silindi', color: 'gray' },
};

const statusOf = (sub) => {
  if (!sub) return 'expired';
  const now = Date.now();
  if (sub.status === 'active') return sub.expiresAt && toDate(sub.expiresAt).getTime() < now ? 'expired' : 'active';
  if (sub.status === 'trial') return sub.trialEndsAt && toDate(sub.trialEndsAt).getTime() < now ? 'expired' : 'trial';
  return sub.status || 'expired';
};

function ActivateForm({ sub, initialDuration, onClose, onSaved }) {
  const [duration, setDuration] = useState(initialDuration || '1m');
  const [note, setNote] = useState(sub.note || '');
  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    const days = PLAN_DAYS[duration];
    const base = sub.status === 'active' && sub.expiresAt && toDate(sub.expiresAt).getTime() > Date.now()
      ? toDate(sub.expiresAt)
      : new Date();
    const expiresAt = Timestamp.fromDate(new Date(base.getTime() + days * 24 * 60 * 60 * 1000));
    await updateSubscription(sub.id, { status: 'active', plan: duration, expiresAt, note });
    setBusy(false);
    onSaved && onSaved();
    onClose();
  };

  return (
    <FormModal title={`Aktifleştir — ${sub.email}`} onSubmit={submit} onClose={onClose} submitLabel="Kaydet">
      <div className="space-y-3">
        <Field label="Süre">
          <Select value={duration} onChange={(e) => setDuration(e.target.value)}>
            {PLAN_OPTIONS.map((p) => <option key={p.key} value={p.key}>{p.label}</option>)}
          </Select>
        </Field>
        <Field label="Not (opsiyonel)"><Input value={note} onChange={(e) => setNote(e.target.value)} placeholder="örn. Havale ile ödendi 01.07.2026" /></Field>
        {busy && <p className="text-xs text-gray-400">Kaydediliyor...</p>}
      </div>
    </FormModal>
  );
}

export default function AdminSubscriptions() {
  const [subs, setSubs] = useState([]);
  const [requests, setRequests] = useState([]);
  const [activating, setActivating] = useState(null);
  const [activatingReqId, setActivatingReqId] = useState(null);
  const [activatingDuration, setActivatingDuration] = useState(null);

  useEffect(() => subscribeAllSubscriptions(setSubs), []);
  useEffect(() => subscribeAllPaymentRequests(setRequests), []);

  const rows = useMemo(
    () => [...subs].sort((a, b) => (toDate(b.createdAt)?.getTime() || 0) - (toDate(a.createdAt)?.getTime() || 0)),
    [subs]
  );

  const pendingRequests = useMemo(
    () => requests.filter((r) => r.status === 'pending').sort((a, b) => (toDate(b.createdAt)?.getTime() || 0) - (toDate(a.createdAt)?.getTime() || 0)),
    [requests]
  );

  const lapsed = useMemo(
    () => rows
      .map((s) => ({ sub: s, info: expiryInfo(s) }))
      .filter((x) => x.info)
      .sort((a, b) => a.info.expiredAt - b.info.expiredAt),
    [rows]
  );
  const needsReminder = lapsed.filter((x) => !x.info.overdue);
  const readyToDelete = lapsed.filter((x) => x.info.overdue);

  const [purgingId, setPurgingId] = useState(null);
  const purgeUser = async (sub) => {
    if (!window.confirm(`${sub.email} hesabının TÜM iş verileri (faturalar, cariler, kasa hareketleri, stoklar, her şey) KALICI OLARAK silinecek. Bu işlem GERİ ALINAMAZ. Devam edilsin mi?`)) return;
    if (!window.confirm('Son onay: verileri şimdi kalıcı olarak sileyim mi?')) return;
    setPurgingId(sub.id);
    try {
      await purgeExpiredUser(sub.id);
    } finally {
      setPurgingId(null);
    }
  };

  const suspend = (sub) => {
    if (!window.confirm(`${sub.email} hesabı askıya alınsın mı?`)) return;
    updateSubscription(sub.id, { status: 'suspended' });
  };

  const reactivateTrial = (sub) => {
    if (!window.confirm(`${sub.email} için deneme süresi yeniden başlatılsın mı (7 gün)?`)) return;
    updateSubscription(sub.id, {
      status: 'trial',
      trialEndsAt: Timestamp.fromDate(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)),
    });
  };

  const openActivate = (sub, reqId = null, duration = null) => { setActivating(sub); setActivatingReqId(reqId); setActivatingDuration(duration); };
  const closeActivate = () => { setActivating(null); setActivatingReqId(null); setActivatingDuration(null); };
  const dismissRequest = (req) => updatePaymentRequest(req.id, { status: 'handled' });
  const activateFromRequest = (req) => openActivate(subs.find((s) => s.id === req.uid) || { id: req.uid, email: req.email }, req.id, req.plan);

  return (
    <div>
      <PageHeader title="Abonelikler" subtitle="Kullanıcı hesaplarını elle onaylayın, uzatın veya askıya alın" />

      <PaymentInfoCard />
      <PricingPlansCard />

      {pendingRequests.length > 0 && (
        <Card title="Ödeme Talepleri" className="mb-6">
          <Table headers={[{ label: 'E-posta' }, { label: 'Paket' }, { label: 'Yöntem' }, { label: 'Tarih' }, { label: '' }]}>
            {pendingRequests.map((r) => (
              <tr key={r.id} className="hover:bg-gray-50">
                <Td className="font-medium text-gray-900">{r.email}</Td>
                <Td className="text-gray-500">{planLabel(r.plan)}</Td>
                <Td><Badge color={r.method === 'havale' ? 'blue' : 'purple'}>{r.method === 'havale' ? 'Havale/EFT' : 'Kredi Kartı'}</Badge></Td>
                <Td className="text-gray-500">{formatDateShort(r.createdAt)}</Td>
                <Td align="right">
                  <div className="flex justify-end gap-2">
                    <Button variant="secondary" onClick={() => dismissRequest(r)}>Kapat</Button>
                    <Button icon={CheckCircle} onClick={() => activateFromRequest(r)}>Aktifleştir</Button>
                  </div>
                </Td>
              </tr>
            ))}
          </Table>
        </Card>
      )}

      {needsReminder.length > 0 && (
        <Card title="Hatırlatma Bekleyen Hesaplar" className="mb-6">
          <p className="px-6 pt-4 text-xs text-gray-500">Aboneliği süresi dolmuş, henüz 3 aylık saklama süresi dolmamış hesaplar. Yenileme hatırlatması için kendileriyle iletişime geçin.</p>
          <Table headers={[{ label: 'E-posta' }, { label: 'Süresi Doldu' }, { label: 'Silinmeye Kalan Süre' }, { label: '' }]}>
            {needsReminder.map(({ sub: s, info }) => (
              <tr key={s.id} className="hover:bg-gray-50">
                <Td className="font-medium text-gray-900">{s.email}</Td>
                <Td className="text-gray-500">{formatDateShort(info.expiredAt)}</Td>
                <Td className="text-gray-500">{formatDateShort(info.deadline)}</Td>
                <Td align="right">
                  <div className="flex justify-end gap-2">
                    <a href={`mailto:${s.email}`} title="E-posta gönder" className="p-2 rounded-full hover:bg-gray-200 text-gray-500"><Mail size={16} /></a>
                    <Button icon={CheckCircle} onClick={() => openActivate(s)}>Aktifleştir</Button>
                  </div>
                </Td>
              </tr>
            ))}
          </Table>
        </Card>
      )}

      {readyToDelete.length > 0 && (
        <Card title="Silinmeye Hazır Hesaplar (3 ay doldu)" className="mb-6">
          <p className="px-6 pt-4 text-xs text-red-600">Bu hesapların 3 aylık saklama süresi doldu. "Kalıcı Olarak Sil" verilerini geri alınamaz şekilde siler.</p>
          <Table headers={[{ label: 'E-posta' }, { label: 'Süresi Doldu' }, { label: '' }]}>
            {readyToDelete.map(({ sub: s, info }) => (
              <tr key={s.id} className="hover:bg-gray-50">
                <Td className="font-medium text-gray-900">{s.email}</Td>
                <Td className="text-gray-500">{formatDateShort(info.expiredAt)}</Td>
                <Td align="right">
                  <Button variant="danger" icon={Trash2} disabled={purgingId === s.id} onClick={() => purgeUser(s)}>
                    {purgingId === s.id ? 'Siliniyor...' : 'Kalıcı Olarak Sil'}
                  </Button>
                </Td>
              </tr>
            ))}
          </Table>
        </Card>
      )}

      <Card>
        {rows.length === 0 ? <EmptyState message="Henüz kayıtlı kullanıcı yok" /> : (
          <Table headers={[{ label: 'E-posta' }, { label: 'Durum' }, { label: 'Plan' }, { label: 'Bitiş / Deneme Sonu' }, { label: 'Not' }, { label: '' }]}>
            {rows.map((s) => {
              const st = statusOf(s);
              const meta = STATUS_META[st] || STATUS_META.expired;
              const dateVal = s.status === 'active' ? s.expiresAt : s.trialEndsAt;
              return (
                <tr key={s.id} className="hover:bg-gray-50">
                  <Td className="font-medium text-gray-900">{s.email}</Td>
                  <Td><Badge color={meta.color}>{meta.label}</Badge></Td>
                  <Td className="text-gray-500">{s.plan === 'trial' ? 'Deneme' : planLabel(s.plan)}</Td>
                  <Td className="text-gray-500">{dateVal ? formatDateShort(dateVal) : '-'}</Td>
                  <Td className="text-gray-400 text-xs max-w-[200px] truncate">{s.note || '-'}</Td>
                  <Td align="right">
                    <div className="flex justify-end gap-1">
                      <button onClick={() => openActivate(s)} title="Aktifleştir / Süre Uzat" className="p-2 rounded-full hover:bg-gray-200 text-green-600"><CheckCircle size={16} /></button>
                      <button onClick={() => reactivateTrial(s)} title="Denemeyi Yenile" className="p-2 rounded-full hover:bg-gray-200 text-blue-500"><RotateCcw size={16} /></button>
                      <button onClick={() => suspend(s)} title="Askıya Al" className="p-2 rounded-full hover:bg-gray-200 text-red-500"><PauseCircle size={16} /></button>
                    </div>
                  </Td>
                </tr>
              );
            })}
          </Table>
        )}
      </Card>
      {activating && (
        <ActivateForm
          sub={activating}
          initialDuration={activatingDuration}
          onClose={closeActivate}
          onSaved={() => { if (activatingReqId) updatePaymentRequest(activatingReqId, { status: 'handled' }); }}
        />
      )}
    </div>
  );
}
